import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int MOD = sc.nextInt();

        int[] DP = new int[N];
        DP[0] = 1;
        int[] Cum = new int[N + 1];
        Cum[1] = 1;

        for (int index = 1; index < N; index++) {
            int i2 = N - index;
            int total = Cum[index];
            int j = 2;
            while (true) {
                if (j > N || i2 * j > N) {
                    break;
                }
                int startIdx = N - i2 * j + 1;
                int endIdx = Math.max(0, N - i2 * j - j + 1);
                total += Cum[startIdx] - Cum[endIdx];
                total %= MOD;
                j++;
            }
            Cum[index + 1] = (Cum[index] + total) % MOD;
            DP[index] = total;
        }
        System.out.println(DP[N - 1]);
        sc.close();
    }
}
